        raise TypeError(f"Quantity must be an integer, got {type(quantity).__name__}.")

    if quantity < 0:
        print(f"Warning: Adding a negative quantity {quantity} for {item_name}.")

    print(f"Attempting to update inventory for item: {item_name}.")

    if item_name in inventory:
        print(f"Item '{item_name}' found. Current quantity: {inventory[item_name]}.")
        inventory[item_name] += quantity
        print(f"New quantity for '{item_name}': {inventory[item_name]}.")
    else:
        print(f"Item '{item_name}' not found. Adding new item.")
        inventory[item_name] = quantity
        print(f"Added new item '{item_name}' with quantity: {quantity}.")

    print(f"Inventory after update: {inventory}.")
    return inventory

