def sort_dicts_by_key(dict_list, key):
    if not isinstance(dict_list, list):
        raise TypeError(f"Expected a list for 'dict_list', but got {type(dict_list).__name__}")
    if not all(isinstance(d, dict) for d in dict_list):
        raise TypeError(f"All elements in 'dict_list' must be dictionaries. Found a non-dict element.")
    if not isinstance(key, str):
        raise TypeError(f"Expected a string for 'key', but got {type(key).__name__}")

    for d in dict_list:
        if key not in d:
            raise ValueError(f"Key '{key}' not found in dictionary: {d}")

    sorted_list = sorted(dict_list, key=lambda d: d[key])

    # Verifying the sort for f-string usage
