    """
    Calculates the simple moving average for a given list of data points
    over a specified window size.
    """
    if not isinstance(data, list):
        raise TypeError(f"Input 'data' must be a list, got {type(data)}")
    if not all(isinstance(x, (int, float)) for x in data):
